\label{thm:abstract}
Assume that $\mathcal S_2$ satisfies the Chernoff conditions above and
that its products admit the even expansion \eqref{eq:product-expansion} through depth
$m$, with $\nu_r=2r$.  For $j=1,\dots,m$, set
\begin{equation}
c_j^{(m)} = (-1)^{m-j}\,\frac{2j^{2m}}{(m-j)!\,(m+j)!},
\label{eq:even-richardson-weights}
\end{equation}
and define the multiproduct
\begin{equation}
\mathcal M_{2m,n}(t) := \sum_{j=1}^mc_j^{(m)}\,\mathcal S_2\!\left(\frac t{jn}\right)^{jn}.
\label{eq:even-richardson-multiproduct}
\end{equation}
Then for every $f\in\mathcal D_m$ and every $0\le t\le h_0n$,
\begin{equation}
\big\|\mathcal M_{2m,n}(t)f-e^{tA}f\big\|_X
\le C'_m e^{\Omega_m t}
\frac{t^{2m+1}}{n^{2m}}
\|f\|_{\mathcal D_m}.
\label{eq:even-richardson-rate}
\end{equation}

\label{prop:resolvent-rate}
Assume the hypotheses of Theorem~\ref{thm:abstract},                                                                  
and let
$\widehat\omega_m:=\max\{\omega,\Omega_m\}$. Then, for every
$f\in\mathcal D_m$ and every $\lambda$ with
$\operatorname{Re}\lambda>\widehat\omega_m$,
\begin{equation}
\left\|\int_0^\infty e^{-\lambda t}\mathcal M_{2m,n}(t)f\,dt
-(\lambda I-A)^{-1}f\right\|_X
\le \frac{C_{\lambda,m}}{n^{2m}}\|f\|_{\mathcal D_m}.
\label{eq:richardson-resolvent-rate}
\end{equation}

Split the error integral at $h_0n$. On $[0,h_0n]$, \eqref{eq:even-richardson-rate} gives
\[
\begin{aligned}
&\int_0^{h_0n}e^{-\operatorname{Re}\lambda t}
 \|\mathcal M_{2m,n}(t)f-e^{tA}f\|_X\,dt\\
&\qquad\le
\frac{C'_m}{n^{2m}}
\int_0^\infty e^{-(\operatorname{Re}\lambda-\Omega_m)t}
 t^{2m+1}\,dt\,\|f\|_{\mathcal D_m},
\end{aligned}
\]
and the integral is finite because
$\operatorname{Re}\lambda>\Omega_m$.
On $[h_0n,\infty)$, the global stability bound \eqref{eq:multiproduct-global-error} gives
\[
 \int_{h_0n}^\infty e^{-\operatorname{Re}\lambda t}
 \|\mathcal M_{2m,n}(t)f-e^{tA}f\|_X\,dt
 \le C_{m,\lambda}e^{-(\operatorname{Re}\lambda-\omega)h_0n}\|f\|_X,
\]

together with the previous proves \eqref{eq:richardson-resolvent-rate}.

\label{prop:UniStabCentDiff}
For every $h\ne0$ and every $f\in L^2(\mathbb R)$,
\begin{equation}
\operatorname{Re}\langle A_hf,f\rangle \le \omega\|f\|^2,
\label{eq:centered-generator-stability}
\end{equation}
 and consequently $\|e^{tA_h}\|\le e^{\omega t}$ for
all $t\ge0$.

\label{lem:half-derivative-commutator}
Let $\beta\in W^{1,\infty}(\mathbb R)$ be real-valued. Then                                            
\begin{equation}
\bigl\|
[\,|D|^{1/2},\beta\,]u
\bigr\|_{L^2}
\le
C
\bigl(
\|\beta\|_\infty\|\beta'\|_\infty
\bigr)^{1/2}
\|u\|_{L^2}.
\label{eq:half-commutator}
\end{equation}
Consequently,
\begin{equation}
\||D|^{1/2}(\beta u)\|_{L^2}
\le
\|\beta\|_\infty\||D|^{1/2}u\|_{L^2}
+
C
\bigl(
\|\beta\|_\infty\|\beta'\|_\infty
\bigr)^{1/2}
\|u\|_{L^2}.
\label{eq:half-product}
\end{equation}

\label{cor:parabolic-richardson}
Assume $a\ge a_0>0$ and
\[
 a\in W^{2m+4,\infty}(\mathbb R),\qquad b\in W^{2m+3,\infty}(\mathbb R),\qquad c\in W^{2m+2,\infty}(\mathbb R).
\]

Then 

$A$ generates an analytic semigroup. For every $\delta>0$, set
$\eta_\delta:=\min\{\delta/2,1\}$. There are constants
$C_{m,\delta},\Omega_{m,\delta}\ge0$ such that, for $0<t\le h_0n$,
\[
 \|\mathcal M_{2m,n}(t)f-e^{tA}f\|_{L^2}
 \le C_{m,\delta}e^{\Omega_{m,\delta}t}
 \frac{t^{2m+\eta_\delta}}{n^{2m}}
 \|f\|_{H^{2m+\delta}}.
\]
In particular, for $f\in H^{2m+2}$,
\[
 \|\mathcal M_{2m,n}(t)f-e^{tA}f\|_{L^2}
 \le C_m e^{\Omega_mt}
 \frac{t^{2m+1}}{n^{2m}}
 \|f\|_{H^{2m+2}}.
\]

\label{cor:schrodinger-richardson}
Under the above assumptions, for every\footnote{Observe that $\mathcal J H^{4m}(\mathbb R)=\mathcal J^{-1}H^{4m}(\mathbb R)=H^{4m}(\mathbb R)$.} $f\in \mathcal J^{-1}H^{4m}=H^{4m}$
and $0\le t\le h_0n$,
\[
 \|\mathcal J^{-1}\mathcal M_{2m,n}(t)\mathcal J f-e^{t A_0}f\|_{L^2}
 \le C_m e^{\Omega_m t}
 \frac{t^{2m+1}}{n^{2m}}
 \|f\|_{H^{4m}}.
\]

\label{cor:dispersive-richardson}
Under the above assumptions, if\footnote{Observe that $\mathcal J H^{5m}(\mathbb R)=\mathcal J^{-1}H^{5m}(\mathbb R)=H^{5m}(\mathbb R)$.} $f\in \mathcal J^{-1}H^{5m}(\mathbb R)=H^{5m}(\mathbb R)$ and
$0\le t\le h_0n$, then
\[
 \|\mathcal J^{-1}\mathcal M_{2m,n}(t)\mathcal J f-e^{tA_0}f\|_{L^2}
 \le C_m e^{\Omega_m t}
 \frac{t^{2m+1}}{n^{2m}}
 \|f\|_{H^{5m}}.
\]

\label{lem:analytic-multiplier}
Let $g\in \mathcal{H}_{\rho_*}$ and $0<\rho<{\rho_*}$. Then
\begin{equation}
\|gf\|_\rho
\le
\sqrt2\,\|g\|_{\mathcal{H}_{\rho_*}}\|f\|_\rho.
\label{eq:analytic-multiplier}
\end{equation}
Moreover, if $0<\rho<\rho_*$, Cauchy's estimate gives
\begin{equation}
\|g^{(q)}\|_{\mathcal{H}_{\rho}}
\le
\frac{q!}{(\rho_*-\rho)^q}\,
\|g\|_{\mathcal{H}_{\rho_*}},
\qquad q\in\mathbb N_0.
\label{eq:coefficient-cauchy}                                            
\end{equation}

\label{lem:analytic-liouville}
Let $\varrho_0>0$ and assume
\[
a\in \mathcal{H}_{\varrho_0}, 
\qquad
a(\bar z)=\overline{a(z)},
\]
and
\[
a(x)\ge a_0>0,
\qquad x\in\mathbb R.
\]


















{}
Then
\begin{equation}
\Re a(z)\ge \frac{a_0}{2},
\qquad z\in \mathscr S_{r_a}.
\label{eq:quantitative-complex-ellipticity}
\end{equation}

For $p\in\{2,3\}$ let
\[
q_p(z):=a(z)^{-1/p},
\]
where the principal branch is taken on the right half-plane.
Then $q_p$ is bounded and holomorphic on $\mathscr S_{r_a}$ and
\begin{equation}
\Re q_p(z)\ge m_p,
\qquad
|q_p(z)|\le M_p,
\qquad z\in \mathscr S_{r_a}.
\label{eq:mp-Mp-bounds}
\end{equation}

{}

Define
\[
\eta_p(z)
:=
\int_0^z q_p(\zeta)\,d\zeta.
\]
Then $\eta_p$ is injective on $\mathscr S_{r_a}$ and
\begin{equation}
S_{m_pr_a}
\subset
\eta_p(S_{r_a}).
\label{eq:eta-covers-strip}
\end{equation}
Consequently
\[
\chi_p:=\eta_p^{-1}
\]
is holomorphic on $\mathscr S_{m_pr_a}$ and satisfies
\begin{equation}
\chi_p(\mathscr S_{\rho_y})
\subset
\mathscr S_{\rho_y/m_p},
\qquad
0<\rho_y<m_pr_a.
\label{eq:chi-strip-inclusion}
\end{equation}
Moreover,
\begin{equation}
\eta_p(\mathscr S_{\rho_x})
\subset
\mathscr S_{M_p\rho_x},
\qquad
0<\rho_x<r_a.
\label{eq:eta-strip-inclusion}
\end{equation}

{}

\label{lem:liouville-analytic-spaces}
Assume the hypotheses of Lemma~\ref{lem:analytic-liouville}.  Set
\[
\vartheta_2:=\frac14,
\qquad
\vartheta_3:=\frac13,
\]
and, for $p=2,3$, define
\[
(\mathcal J_pf)(y)
:=
a(\chi_p(y))^{-\vartheta_p}
f(\chi_p(y)).
\]
Then the following assertions hold. 

If
\begin{equation}
0<\rho_y<m_p\rho_x,
\qquad
0<\rho_x<r_a,
\label{eq:J-compatible-radii}
\end{equation}
then
\begin{equation}
\mathcal J_p:
\mathcal A_{\rho_x}
\longrightarrow
\mathcal A_{\rho_y}
\label{eq:J-map-analytic}
\end{equation}
is bounded. 

Conversely, if
\begin{equation}
0<M_p\rho_x<\rho_y<m_pr_a,
\label{eq:Jinv-compatible-radii}
\end{equation}
then
\begin{equation}
\mathcal J_p^{-1}:
\mathcal A_{\rho_y}
\longrightarrow
\mathcal A_{\rho_x}
\label{eq:Jinv-map-analytic}
\end{equation}
is bounded.

In particular, $\mathcal J_p$ and $\mathcal J_p^{-1}$ identify the
original and normalized analytic scales up to the radius distortion
controlled by $m_p$ and $M_p$.

\label{lem:analytic-commutator}
\begin{equation}
 \|[W_\rho,g]u\|_2
 \le \rho M_1(g;\rho)\|W_\rho u\|_2.
\label{eq:analytic-commutator}
\end{equation}

\label{prop:analytic-group}
Assume that $v$ is real-valued and $v,w\in\mathcal{H}_{\rho_*}$ for some
$\rho_*>0$.  Fix $0<\rho_0<\rho_*$.  Then there exist 
$C_0\ge 1$ and $\kappa,\Gamma\ge0$,
depending on $\rho_0$ and on the bounded analytic norms of $v,w$, but
independent of $h$, such
that
\begin{equation}
 \|e^{tL_{p,h}}f\|_{\rho_0e^{-\kappa|t|}}
 \le C_0 e^{\Gamma|t|}\|f\|_{\rho_0},
 \qquad t\in\mathbb R,

\label{eq:analytic-group-propagation-new}
\end{equation}
for $p=2,3$ and $h\in\mathbb R$.   
{}

\label{prop:analytic-parabolic}
Assume $a$ is real, $a(x)\ge a_0>0$, and
$a,\varphi,p_0\in\mathfrak W_R$ for some $R>0$.  Choose
$0<\rho_0<R$ sufficiently small that
\begin{equation}
 \rho_0M_1(a;\rho_0)\le \frac{a_0}{2}.
\label{eq:parabolic-dissipation}
\end{equation}
Then there exist $\kappa,\Gamma\ge0$, independent of $h$, such that
\begin{equation}
 \|e^{tA_h}f\|_{\rho_0e^{-\kappa t}}
 \le e^{\Gamma t}\|f\|_{\rho_0},
 \qquad t\ge0.
\label{eq:analytic-parabolic-propagation}
\end{equation}
The same estimate holds for $A=A_0$.

\label{lem:analytic-defects}
For each of the three centered-difference models, let $p=2$ for the
parabolic and Schr\"odinger cases and $p=3$ for the cubic case.  Under
the analytic coefficient hypotheses above, there exist $A_*,B_*>0$
such that, for $0<\rho'<\rho\le\rho_0$,
\begin{equation}
 \|R_rf\|_{\rho'}
 \le
 A_*B_*^r
 \frac{\Gamma(2r+p+1)}{(\rho-\rho')^{2r+p}}
 \|f\|_\rho,
 \qquad r\ge1.
\label{eq:analytic-defect-bound}
\end{equation}
Moreover, if
\[
 A_h=A+\sum_{r=1}^{m-1}h^{2r}R_r+h^{2m}Q_m(h),
\]
then there exist model-dependent constants $\theta_*,A_1,B_1>0$,
independent of $m$, $h$, $\rho$, and $\rho'$, such that
\[
 \|Q_m(h)f\|_{\rho'}
 \le A_1B_1^m(\rho-\rho')^{-(2m+p)}\|f\|_\rho
\]
whenever $|h|\le\theta_*(\rho-\rho')$. 
{}

\label{thm:analytic-bridge}
Assume the hypotheses of Proposition~\ref{prop:analytic-parabolic} in
the parabolic case, or Proposition~\ref{prop:analytic-group} in the
normalized Schr\"odinger/cubic cases, and let
$f\in\mathcal A_{\rho_0}$.  Let $p=2$ in the two second-order cases and
$p=3$ in the cubic case.  Then for every $T>0$ and every
$0<\rho_*<\rho_1e^{-\kappa T}$ there exist constants $C_T,K_T>0$ and
$N_T\ge1$, independent of $f$, $m$, and $N$, such that, for every $N\ge N_T$ and every $0\le t\le T$,
\begin{equation}
 \left\|
 \mathcal S_2(t/N)^Nf-e^{tA}f
 -\sum_{r=1}^{m-1}\frac{E_{2r}(t)f}{N^{2r}}
 \right\|_{\rho_*}
 \le
 C_TK_T^m\Gamma((p+1)m+1)e^{\Gamma t}
 \frac{t^{2m+1}}{N^{2m}}\,
 \|f\|_{\rho_0}.
\label{eq:analytic-bridge-estimate}
\end{equation}
In particular, the analytic product expansion realizes the pointwise
form \eqref{eq:product-expansion} on every fixed strip interval, with
\[

 {\ C^{\rm an}_{m,T}\le C_TK_T^m\Gamma((p+1)m+1).                         
 \ }
\]
{}

\label{lem:optimized-analytic-bound}There exists $C_T,K_*>0$ such that
\begin{equation}
 \|\mathcal M_{2m,n}(t)f-e^{tA}f\|_{\rho_*}
 \le C_T e^{\Gamma t}t
 \left(\frac{K_*t^2m^{p-1}}{n^2}\right)^m
 \|f\|_{\rho_0},\qquad 0\le t\le T,
\label{eq:optimized-preliminary-bound}
\end{equation}
for all $n\ge N_T$, with $N_T$ as in Theorem~\ref{thm:analytic-bridge}.

For the even nodes $1,2,\dots,m$, recall
\[
 c_j^{(m)}=(-1)^{m-j}\frac{2j^{2m}}{(m-j)!(m+j)!}.
\]


Then every refined step count
$N=jn$, $1\le j\le m$, also satisfies $N\ge N_T$, so the theorem applies
to every product entering the Richardson extrapolation.  
The exact weighted identity
\begin{equation}
 \sum_{j=1}^m\frac{|c_j^{(m)}|}{j^{2m}}
 =\frac{4^m-\binom{2m}{m}}{(2m)!}
 <\frac{4^m}{\Gamma(2m+1)}
\label{eq:richardson-weight-identity}
\end{equation}
then turns Theorem~\ref{thm:analytic-bridge} into
\begin{equation}
 \|\mathcal M_{2m,n}(t)f-e^{tA}f\|_{\rho_*}
 \le
 C_T(4K_T)^m e^{\Gamma t}
 \frac{\Gamma((p+1)m+1)}{\Gamma(2m+1)}
 \frac{t^{2m+1}}{n^{2m}}
 \|f\|_{\rho_0},\qquad 0\le t\le T.
\label{eq:richardson-weight-bound}
\end{equation}
Stirling's formula then yields \eqref{eq:optimized-preliminary-bound}.

\label{cor:evolution-representation}
For each of the three analytic model classes, the solution of the
Cauchy problem \emph{(CP)} admits the Richardson--Chernoff representation
\begin{equation}
 u(t)=e^{tA}f
 =\lim_{n\to\infty}
 \sum_{j=1}^{m(n)}c_j^{(m(n))}
 \mathcal S_2\!\left(\frac{t}{jn}\right)^{jn}f,
 \qquad 0\le t\le T,
 \label{eq:evolution-representation}
\end{equation}
with convergence in $\mathcal A_{\rho_*}$, uniformly on $[0,T]$.
For the parabolic and Schr\"odinger-type second-order equations the
error is $O(e^{-cn^2})$, whereas for the third-order dispersive equation
it is $O(e^{-cn})$.
